ST.xhtml:
IF nState = 1000 THEN fb_GearInDyn( Master:=refMaster_Axis , Slave:=Axis , Enable:=bActivateGearIn OR bTestGearIn , GearRatio:=rGearingRatio , Acceleration:= , Deceleration:= , Jerk:= , BufferMode:= , Options:= , InGear=>bInGear , Busy=> , Active=> , CommandAborted=> , Error=> , ErrorID=> );
ctuGearIn( CU:=bActivateGearIn , RESET:= , PV:= , Q=> , CV=> ); END_IF
ctuGearIn.CV;

// Read Manual veolcity from drive
	fbGetManualVelo(
			Axis:= Axis, 
			Enable:= TRUE, 
			ParameterNumber:=MC_AxisParameter.AxisManualVelocityFast,
			ReadMode:= Tc2_MC2.READMODE_CYCLIC,
			Value=>lrManualVelo );

IF bManual THEN
// Set current Manual speed (HMI csúszka alapján %-osan számolja
	fbJog.Velocity:=(lrMAnualOverride/100)*lrManualVelo;
ELSE
// Set current AUTOMATIC speed (HMI csúszka alapján %-osan számolja
	fbJog.Velocity:=(lrMAnualOverride/100)*rP2Jog;
END_IF




(*IF (nState = 1000 OR fbJog.Error)	AND				    // If it is in error, it should be possible to acknowledge it
   (NOT bAutomatic OR bJogMovementInAuto)				// Only go to JOG when Drive is ready and not doing anything else and Manual is in the cell 
THEN*)
fbJog(
	Axis:= Axis, 
	JogForward:= bJogForward,  
	JogBackwards:= bJogBackwards,  
	Mode:=e_JogMode , 
	Position:=rJogInching , 
	Velocity:= , 
	Acceleration:= , 
	Deceleration:= , 
	Jerk:= , 
	Done=> , 
	Busy=> , 
	Active=> , 
	CommandAborted=> , 
	Error=> , 
	ErrorID=> );

(*END_IF *)

	fbJog.JogForward;
	fbJog.JogBackwards;
	fbJog.Mode;
	fbJog.Velocity;
	fbJog.Position;
	fbJog.Acceleration;
	fbJog.Deceleration;
	fbJog.Jerk;
	fbJog.Done;
	fbJog.Busy;
	fbJog.Active;
	fbJog.CommandAborted;
	fbJog.Error;
	fbJog.ErrorID;

IF bEMYOK THEN IF NOT bPosLimitRead THEN
GetSoft_PosLimit( Axis:= Axis, Enable:= NOT GetSoft_PosLimit.Busy AND NOT GetSoft_PosLimit.Error AND NOT SetSoft_PosLimit.Execute , ParameterNumber:=MC_AxisParameter.SWLimitPos, ReadMode:= Tc2_MC2.READMODE_CYCLIC, Value=>lrPosLimit ); rMaxPosLimit:=lrPosLimit-2;
IF GetSoft_PosLimit.Valid THEN bPosLimitRead:=TRUE; END_IF END_IF
IF NOT bMinLimitRead THEN GetSoft_NegLimit( Axis:= Axis, Enable:= NOT GetSoft_NegLimit.Busy AND NOT GetSoft_NegLimit.Error AND NOT SetSoft_NegLimit.Execute, ParameterNumber:= MC_AxisParameter.SWLimitNeg, ReadMode:= Tc2_MC2.READMODE_CYCLIC, Value=>lrNegLimit );
rMinPosLimit:=lrNegLimit+2;
IF GetSoft_NegLimit.Valid THEN bMinLimitRead:=TRUE; END_IF END_IF
IF lrPosLimit <> 0 THEN // Ha nincs beállítva akkor ne írja be a nullás értéket SetSoft_PosLimit( Axis:= Axis, Execute:= NOT GetSoft_PosLimit.Busy AND GetSoft_PosLimit.Valid AND GetSoft_PosLimit.Value <> lrPosLimit, ParameterNumber:= 2, Value:= lrPosLimit); END_IF;
IF lrNegLimit <> 0 THEN // Ha nincs beállítva akkor ne írja be a nullás értéket SetSoft_NegLimit( Axis:= Axis, Execute:= NOT GetSoft_NegLimit.Busy AND GetSoft_NegLimit.Valid AND GetSoft_NegLimit.Value <> lrNegLimit, ParameterNumber:= 3, Value:= lrNegLimit); END_IF
END_IF

(*Hibakezelés*)
IF nState > 0
	AND nState < 10000
THEN
	nStatePrevious := nState;
END_IF

(*Emergency*)

IF NOT bEMYOK THEN
	nState := 0;
	bBusy:= FALSE;
	bDone:= FALSE;
END_IF

IF bHalt THEN
	bHalt:=FALSE;
	Halt.Execute := TRUE;
	bHaltDone:=FALSE;
ELSIF Halt.Done THEN
	bHaltDone:=TRUE;
	Halt.Execute := FALSE;
END_IF
// Override ellenőrzése, nem lehet nagyobb mint 100%
IF rOverride > 100 THEN
 	rOverride:=100;
ELSIF rOverride < 1 THEN 
	rOverride:=1;
END_IF

IF lrMAnualOverride > 100 THEN 
	 lrMAnualOverride:=100;
ELSIF lrMAnualOverride < 1 THEN 
	lrMAnualOverride:=1;
END_IF
//(*Error*)
//sError := '';
//bError := FALSE;

Axis.Status.DriveDeviceError;
Axis.Status.Error;
PowerAxisOut.Error;
MoveAbsoluteOut1.CommandAborted;
MoveAbsoluteOut1.Error;
ResetOut.Error;
SoEResetOut.Error;
PowerAxis.Error;
MoveAxis1.CommandAborted;
MoveAxis1.Error;

tonbEMYOK(IN:=bEMYOK , PT:=T#1S , Q=> , ET=> );

rtrigbEMYOK(CLK:=tonbEMYOK.Q , Q=> );

IF rtrigbEMYOK.Q THEN
	bEMYOKisBack:=TRUE;
END_IF

IF i_uiSlaveINnOp = 8  THEN // Ne dobáljon hibát ha nem megy még az EtherCat
	fb_ErrorHandling(
		bEnable:=TRUE , 
		sName:=sName , 
		arrsErrorString:= , 
		arrbError:= , 
		arrOEEErrorCode:= , 
		sERROR=>sError , 
		bERROR=>bError , 
		iOEECategoryNumber=>iOEECategoryNumber , 
		bErrorStringConfirmed:=bErrorStringConfirmed );

	// Set ERROR Array
	// PowerAxis ERROR
	fb_ErrorHandling.arrbError[0]:=PowerAxisOut.Error;
	fb_ErrorHandling.arrsErrorString[0]:=CONCAT(sName,concat(FC_Locale('',' MC_Power hiba, hibakód: ',' MC_Power error, error code: '),UDINT_TO_STRING(PowerAxisOut.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[0]:=2136;	

	// MoveAxis1 ERROR
	fb_ErrorHandling.arrbError[1]:=MoveAxis1.Error;
	fb_ErrorHandling.arrsErrorString[1]:=CONCAT(sName,concat(FC_Locale('',' MC_MoveAbsolute 1  hiba, hibakód: ',' MC_MoveAbsolute 1 error, error code: ') ,UDINT_TO_STRING(MoveAxis1.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[1]:=2136;	

	// MoveAxis2 ERROR
	fb_ErrorHandling.arrbError[2]:=MoveAxis2.Error;
	fb_ErrorHandling.arrsErrorString[2]:=CONCAT(sName,concat(FC_Locale('',' MC_MoveAbsolute 2 hiba, hibakód: ',' MC_MoveAbsolute 2 error, error code: '),UDINT_TO_STRING(MoveAxis2.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[2]:=2136;	

	// RESET ERROR
	fb_ErrorHandling.arrbError[3]:=Reset.Error;
	fb_ErrorHandling.arrsErrorString[3]:=CONCAT(sName,concat(FC_Locale('',' MC_Reset hiba, hibakód: ',' MC_Reset error, error code: '),UDINT_TO_STRING(Reset.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[3]:=2136;	

	// SOE_RESET ERROR
	fb_ErrorHandling.arrbError[4]:=SoEReset.Error;
	fb_ErrorHandling.arrsErrorString[4]:=CONCAT(sName,concat(FC_Locale('',' FB_SoEReset hiba, hibakód: ',' FB_SoEReset error, error code: ') ,UDINT_TO_STRING(SoEReset.AdsErrId)));
	fb_ErrorHandling.arrOEEErrorCode[4]:=2136;	

	// HOME ERROR
	fb_ErrorHandling.arrbError[5]:=Home.Error;
	fb_ErrorHandling.arrsErrorString[5]:=CONCAT(sName,concat(FC_Locale('',' Homing hiba, hibakód: ',' Homing error, error code: ') ,UDINT_TO_STRING(Home.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[5]:=2136;	

	// Jog ERROR
	fb_ErrorHandling.arrbError[6]:=fbJog.Error;
	fb_ErrorHandling.arrsErrorString[6]:=CONCAT(sName,concat(FC_Locale('',' Jog hiba, hibakód: ',' Jog error, error code: '),UDINT_TO_STRING(fbJog.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[6]:=2136;

	// Halt ERROR
	fb_ErrorHandling.arrbError[7]:=Halt.Error;
	fb_ErrorHandling.arrsErrorString[7]:=CONCAT(sName,concat(FC_Locale('',' Halt hiba, hibakód: ',' Halt error, error code: '),UDINT_TO_STRING(Halt.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[7]:=2136;

	// fb_DriveDiag ERROR
	fb_ErrorHandling.arrbError[8]:=fb_DriveDiag.Error;
	fb_ErrorHandling.arrsErrorString[8]:=CONCAT(sName,concat(FC_Locale('',' DriveDiag hiba, hibakód: ',' DriveDiag error, error code: '),UDINT_TO_STRING(fb_DriveDiag.AdsErrId)));
	fb_ErrorHandling.arrOEEErrorCode[8]:=2136;

	// GetSoft_NegLimit ERROR
	fb_ErrorHandling.arrbError[9]:=GetSoft_NegLimit.Error;
	fb_ErrorHandling.arrsErrorString[9]:=CONCAT(sName,concat(FC_Locale('',' GetSoft_NegLimit hiba, hibakód: ',' GetSoft_NegLimit error, error code: '),UDINT_TO_STRING(GetSoft_NegLimit.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[9]:=2136;

	// SetSoft_NegLimit ERROR
	fb_ErrorHandling.arrbError[10]:=SetSoft_NegLimit.Error;
	fb_ErrorHandling.arrsErrorString[10]:=CONCAT(sName,concat(FC_Locale('',' SetSoft_NegLimit hiba, hibakód: ',' SetSoft_NegLimit error, error code: '),UDINT_TO_STRING(SetSoft_NegLimit.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[10]:=2136;

	// GetSoft_PosLimit ERROR
	fb_ErrorHandling.arrbError[11]:=GetSoft_PosLimit.Error;
	fb_ErrorHandling.arrsErrorString[11]:=CONCAT(sName,concat(FC_Locale('',' GetSoft_PosLimit hiba, hibakód: ',' GetSoft_PosLimit error, error code: '),UDINT_TO_STRING(GetSoft_PosLimit.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[11]:=2136;

	// SetSoft_PosLimit ERROR
	fb_ErrorHandling.arrbError[12]:=SetSoft_PosLimit.Error;
	fb_ErrorHandling.arrsErrorString[12]:=CONCAT(sName,concat(FC_Locale('',' SetSoft_PosLimit hiba, hibakód: ',' GetSoft_PosLimit error, error code: '),UDINT_TO_STRING(SetSoft_PosLimit.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[12]:=2136;

	// Drive ERROR
	fb_ErrorHandling.arrbError[13]:=Axis.Status.DriveDeviceError;
	fb_ErrorHandling.arrsErrorString[13]:=CONCAT(STR1:= sName, STR2:= FC_Locale('',' drive hiba ',' Drive error '));
	fb_ErrorHandling.arrOEEErrorCode[13]:=2136;

	// ERROR
	fb_ErrorHandling.arrbError[14]:=Axis.Status.Error;
	fb_ErrorHandling.arrsErrorString[14]:=CONCAT(STR1:= sName, STR2:=FC_Locale('',' hiba ',' error '));
	fb_ErrorHandling.arrOEEErrorCode[14]:=2136;	

	// Gearing ERROR
	fb_ErrorHandling.arrbError[15]:=fb_GearInDyn.Error;
	fb_ErrorHandling.arrsErrorString[15]:=CONCAT(sName,concat(FC_Locale('',' Kuplungolási hiba, hibakód: ',' Coupling error, error code: ') ,UDINT_TO_STRING(fb_GearInDyn.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[15]:=2136;	

	// GearOut ERROR
	fb_ErrorHandling.arrbError[16]:=fb_GearOut.Error;
	fb_ErrorHandling.arrsErrorString[16]:=CONCAT(sName,concat(FC_Locale('', ' Kuplung szétkapcsolási hiba, hibakód: ',' Decoupling error, error code: ') ,UDINT_TO_STRING(fb_GearOut.ErrorID)));
	fb_ErrorHandling.arrOEEErrorCode[16]:=2136;	

	// Sequence ERROR
	fb_ErrorHandling.arrbError[17];
	fb_ErrorHandling.arrsErrorString[17];
	fb_ErrorHandling.arrOEEErrorCode[17];
END_IF
(* update the axis status at the beginning of each cycle *)
Axis();
(******************************************************************* Step sequence archive*)
IF bClr THEN
	arr_Step_Archive:=arrClr_Step_Archive;
	bClr:=FALSE;
END_IF

IF arr_Step_Archive[0] <> nState THEN
	FOR i:=40 TO 1 BY -1 DO
		arr_Step_Archive[i]:= arr_Step_Archive[i-1];
	END_FOR
		arr_Step_Archive[0]:= nState;
END_IF

arr_Step_Archive[0];
arr_Step_Archive[1];
arr_Step_Archive[2];
arr_Step_Archive[3];
arr_Step_Archive[4];
arr_Step_Archive[5];
arr_Step_Archive[6];
arr_Step_Archive[7];
arr_Step_Archive[8];
arr_Step_Archive[9];
arr_Step_Archive[10];
arr_Step_Archive[11];
arr_Step_Archive[12];
arr_Step_Archive[13];
arr_Step_Archive[14];
arr_Step_Archive[15];
arr_Step_Archive[16];
arr_Step_Archive[17];
arr_Step_Archive[18];
arr_Step_Archive[19];
arr_Step_Archive[20];
arr_Step_Archive[21];
arr_Step_Archive[22];
arr_Step_Archive[23];
arr_Step_Archive[24];
arr_Step_Archive[25];
arr_Step_Archive[26];
arr_Step_Archive[27];
arr_Step_Archive[28];
arr_Step_Archive[29];
arr_Step_Archive[30];


fbRunTrig(CLK:= bGoPosition, Q=> );
rtrig_ManualMove(CLK:=bGoPosition_Manual, Q=> );

IF rtrig_ManualMove.Q THEN
	bThisIsManualMovement:=TRUE;
END_IF

CASE nState OF
	(* Vészkör bontva - Alaphelyzet felvétel *)
	0:(* Működtetések törlése - Vészkör ellenőrzés *)
		MoveAxis1.Execute := FALSE;
		MoveAxis2.Execute := FALSE;
		Reset.Execute := FALSE;
		PowerAxis.Enable := FALSE;
		Home.Execute := FALSE;
		bReady:=FALSE;
		bThisIsManualMovement:=FALSE;

		IF bEMYOK THEN
			IF Axis.Status.Error
				OR Axis.Status.DriveDeviceError
			THEN
				nState := 15000;
			ELSIF bAxisEnabled THEN
				nState := nState + 10;
			END_IF
		END_IF

	10: (*Tengely engedélyezése*)
		PowerAxis.Enable := TRUE;
		IF PowerAxis.Status THEN
			IF bIncremental THEN
				IF bStandAlone THEN
					nState := nState + 10;
				END_IF
			ELSE
				nState := 1000;
			END_IF

		ELSIF PowerAxis.Error THEN
			nState := 15000;
		END_IF		

	20: (*Home OK?*)
		IF Axis.Status.Homed THEN
			nState := 1000;
		END_IF

	30: (*Parancsra vár*)
		IF fbRunTrig.Q THEN
			bDone:= FALSE;
			bBusy:= TRUE;
			nState := nState + 10;
		END_IF

	40: (*Home-olás*)
		Home.Execute := TRUE;
		IF Home.Done THEN
			Home.Execute := FALSE;
			bBusy:= FALSE;
			bDone:= TRUE;
			nState := 1000;
		ELSIF Home.CommandAborted OR Home.Error THEN
			nState := 15000;
		END_IF		

	(* Automata mód - Alaphelyzet *)
	1000: (*Parancsra vár*)
		bReady:=TRUE;
		IF (fbRunTrig.Q OR rtrig_ManualMove.Q)AND bStandAlone AND NOT bActivateGearIn AND NOT bInGear // OK
			AND ( rVelocity1 > 0 
					OR rVelocity2 > 0 ) THEN
			bReady:=FALSE;
			bDone:= FALSE;
			bBusy:= TRUE;
			nState := nState + 10;		
		ELSIF NOT bAxisEnabled THEN
				nState :=0;
		END_IF
		IF Axis.Status.Error																		// ERROR
			OR Axis.Status.DriveDeviceError	THEN
				nState := 15000;
				fb_ErrorHandling.arrsErrorString[17]:='Axis in ERROR!';
				bReady:=FALSE;
		ELSIF (fbRunTrig.Q OR  rtrig_ManualMove.Q)		// 0-ás sebességgel akarják mozgatni a szervót
			AND ( rVelocity1 = 0 
					AND rVelocity2 = 0 ) THEN
			fb_ErrorHandling.arrbError[17]:=TRUE;
			fb_ErrorHandling.arrsErrorString[17]:=FC_Locale('', 'Nincs sebesség megadva a szervó mozgatásához!','No velocity set for the movement!');
			nState := 15000;
			bReady:=FALSE;
		ELSIF (fbRunTrig.Q OR  rtrig_ManualMove.Q)		// Requested position is below negativ limit switch
			AND rPosition1 < lrNegLimit THEN
			fb_ErrorHandling.arrbError[17]:=TRUE;
			fb_ErrorHandling.arrsErrorString[17]:=FC_Locale('', 'Meghívott pozíció negatív limitswithc alatt!','Requested position is below limit switch!');
			nState := 15000;
			bReady:=FALSE;	
		ELSIF (fbRunTrig.Q OR  rtrig_ManualMove.Q)		// Requested position is below negativ limit switch
			AND rPosition1 > lrPosLimit THEN
			fb_ErrorHandling.arrbError[17]:=TRUE;
			fb_ErrorHandling.arrsErrorString[17]:=FC_Locale('', 'Meghívott pozíció pozitív limitswitch felett!','Requested position is above limit switch!');
			nState := 15000;
			bReady:=FALSE;
		END_IF

	1010: (*Pozícióra*)
		MoveAxis1.Position := rPosition1;
		IF bThisIsManualMovement THEN 
			MoveAxis1.Velocity := (rVelocity1*(lrMAnualOverride/100));
		ELSE
			MoveAxis1.Velocity := (rVelocity1*(rOverride/100));
		END_IF
		MoveAxis1.BufferMode := MC_Buffered;
		MoveAxis1.Execute := TRUE;
		(*Közvetlen pozícióra*)
		IF NOT bBufferedMove THEN
			IF MoveAxis1.Done THEN
				MoveAxis1.Execute := FALSE;
				bBusy:= FALSE;
				bDone:= TRUE;
				nState := 1000;
			ELSIF MoveAxis1.CommandAborted OR MoveAxis1.Error THEN
				nState := 15000;
				IF MoveAxis1.CommandAborted THEN 
					fb_ErrorHandling.arrsErrorString[17]:='MC_MoveAbsolute 1 command aborted!';
				END_IF
			END_IF
		ELSE
		(*Van buffer parancs*)
			IF MoveAxis1.Active THEN
				MoveAxis1.Execute := FALSE;
				nState := 1020;
			ELSIF MoveAxis1.CommandAborted OR MoveAxis1.Error THEN
				nState := 15000;
				IF MoveAxis1.CommandAborted THEN 
					fb_ErrorHandling.arrsErrorString[17]:='MC_MoveAbsolute 1 command aborted!';
				END_IF
			END_IF	
		END_IF

	1020: (*Buffer*)
		MoveAxis2.Position := rPosition2;
		MoveAxis2.Velocity := (rVelocity2*(rOverride/100));
		MoveAxis2.BufferMode := MC_BlendingLow;
		MoveAxis2.Execute := TRUE;
		IF MoveAxis2.Done THEN
			MoveAxis2.Execute := FALSE;
			bBusy:= FALSE;
			bDone:= TRUE;
			nState := 1000;
		ELSIF MoveAxis2.CommandAborted OR MoveAxis2.Error THEN
			nState := 15000;
			IF MoveAxis2.CommandAborted THEN 
				fb_ErrorHandling.arrsErrorString[17]:='MC_MoveAbsolute 2 command aborted!';
			END_IF
		END_IF

	15000:(* Hiba *)
		bReady:=FALSE;
		bBusy := FALSE;
		fb_ErrorHandling.arrbError[17]:=TRUE;
		nState := 15010;
		iOEECategoryNumber:=2136;

	15010:(* Hibanyugta *)
		IF bErrorAck 
			OR (bEMYOKisBack AND bActivateGearIn) THEN		// Kéziekrékre van kuplungolva nyitva van az ajtó és nyomogatják a dead-man gombot
				iOEECategoryNumber:=0;
				Halt.Execute := FALSE;
				bHaltDone:=FALSE;
				bEMYOKisBack:=FALSE;

				IF Axis.Status.DriveDeviceError THEN (* axis drive error requires reset *)
					SoEReset.Execute := TRUE;
					nState := 15020;
				ELSIF Axis.Status.Error THEN (* axis error requires reset *)
					Reset.Execute := TRUE;
					nState := 15030;
				ELSE
					nState := 0;
				END_IF
				fb_ErrorHandling.arrbError[17]:=FALSE;
				fb_ErrorHandling.arrsErrorString[17]:='';
		END_IF

	15020: (*Drive Reset*)
		IF NOT SoEReset.Busy THEN
			SoEReset.Execute := FALSE;
			nState := 15025;
		ELSIF SoEReset.Error THEN
			nState := 0; (* can't do anything here *)
		END_IF	

	15025:
		IF Axis.Status.Error THEN (* axis error requires reset *)
				Reset.Execute := TRUE;
				nState := 15030;
		ELSE
				nState := 0;
		END_IF;

	15030: (*Reset*)
		IF Reset.Done THEN
			Reset.Execute := FALSE;
			nState := 0;
		ELSIF Reset.Error THEN
			nState := 0; (* can't do anything here *)
		END_IF	
END_CASE

ActPower();	(* call the power function block *)

ActMove();	(* call the move function block *)
ActReset();	(* call the reset function block *)
ActSoEReset();	(* call the SoEreset function block *)
ActHome();	(* call the home function block *)
ActJog();
ActHalt();
ActSetLimits();
ActGearInDyn();
ActGearOut();

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK FB_Motor
VAR_INPUT
	sName				:STRING;
	bEMYOK				:BOOL;
	bStandAlone			:BOOL := TRUE; //nincs NCI-be összekapcsolva: önállóan használható
	bErrorAck			:BOOL;
	bDisableManualCmd	:BOOL;	(*Manual control disable*)
// Gearing
	bActivateGearIn		:BOOL;	// Tengely kuplungolása Master-el, pl. Handwheel
	bGearOut			:BOOL;
	refMaster_Axis		:AXIS_REF;
	rGearingRatio		:REAL;

	rPosition1			:REAL;
	rVelocity1			:REAL;
	bBufferedMove		:BOOL;
	rPosition2			:REAL;
	rVelocity2			:REAL;
	rOverride			:REAL:=10;
	bGoPosition			:BOOL;	// Automatic movement called by the PLC program
	bGoPosition_Manual	:BOOL;	// Manual movement called by the HMI
	bEnablePositive		:BOOL := TRUE;
	bEnableNegative		:BOOL := TRUE;
	bIncremental		:BOOL := FALSE;	//True: Incremental encoder, false: absolut encoder
	bCalibrationCam		:BOOL;	//Véghelyzet érzékelő
	bHalt				:BOOL;
	bAxisEnabled		:BOOL;
	lrNegLimit			:LREAL;	
	lrPosLimit			:LREAL;
	rMinVelocity		:REAL;
	rMaxVelocity		:REAL;
	bErrorStringConfirmed	:BOOL; // Hibakezelő blokknak kell, ha a külső app feldolgozta az adott hibastringet akkor bebillenti, reset a blokkban történik
// Jog mode
	e_JogMode			:E_JogMode:=MC_JOGMODE_INCHING;
	bJogForward			:BOOL;
	bJogBackwards		:BOOL;
	bJogMovementInAuto	:BOOL;  // Ha Automatában kell JOG-ban mozogni. pl. AX5000-el hajtott körasztal 
	rJogInching			:REAL:=0.1;
	rP2Jog				:REAL:=50;
	lrMAnualOverride	:LREAL:=10;
END_VAR
VAR_OUTPUT
	/// axis reference data structure 
	Axis				:AXIS_REF;
	bInGear				:BOOL;
	bReady				:BOOL;
	bBusy				:BOOL;
	bDone				:BOOL;
	bHaltDone			:BOOL;
	bError				:BOOL;
	sError				:STRING(255);(*hiba string*)
	iOEECategoryNumber	:INT;	(*OEE Kategória MES adatbázisnak*)
END_VAR

VAR_IN_OUT

END_VAR

VAR
	nState				:UINT;
	nStatePrevious		:UINT;
	fbRunTrig			:R_TRIG;		(*Indulás trigger*)	

	PowerAxis			:MC_Power;
	PowerAxisOut		:ST_McOutputs;
	MoveAxis1			:MC_MoveAbsolute;
	MoveAbsoluteOut1	:ST_McOutputs;
	MoveAxis2			:MC_MoveAbsolute;
	MoveAbsoluteOut2	:ST_McOutputs;
	Reset				:MC_Reset;
	ResetOut			:ST_McOutputs;
	SoEReset			:FB_SoEReset;
	SoEResetOut			:ST_McOutputs;
	Home				:MC_Home;
	HomeOut				:ST_McOutputs;
	fbJog				:MC_Jog;
	fb_GearInDyn		:MC_GearInDyn;
	fb_GearOut			:MC_GearOut;

	i_uiSlaveINnOp		AT %I*	:UINT;

	rMinPosLimit		:REAL;
	rMaxPosLimit		:REAL;

	Halt				:MC_Halt;
	HaltOut				:ST_McOutputs;
	fb_DriveDiag		:FB_SoEReadDiagNumber;
	bIsInitalized		:BOOL;
//	fbAlarm				:FB_TcAlarm;
	nGlobalAxisErrorID	:UDINT;
	GetSoft_NegLimit	:Tc2_MC2.MC_ReadParameter;
	SetSoft_NegLimit	:Tc2_MC2.MC_WriteParameter;
	GetSoft_PosLimit	:Tc2_MC2.MC_ReadParameter;
	SetSoft_PosLimit	:Tc2_MC2.MC_WriteParameter;	

	fbGetManualVelo		:Tc2_MC2.MC_ReadParameter;
	lrManualVelo		:LREAL;



	fb_ErrorHandling	:FB_ERROR_Handling_For_FBs;
	bTestGearIn			: BOOL;
	bTestGearOut		: BOOL;
