	rtrigbEMYOK			: R_TRIG;
	bEMYOKisBack		: BOOL;
	bLimitsAreSet		: BOOL;
	bPosLimitRead		: BOOL;
	bMinLimitRead		: BOOL;

	bClr				:BOOL;
	arr_Step_Archive	:ARRAY[0..30] OF UINT;
	arrClr_Step_Archive	:ARRAY[0..30] OF UINT;
	i					:INT;
	rtrig_ManualMove: R_TRIG;
	bThisIsManualMovement: BOOL;
	tonbEMYOK			:TON;
END_VAR
